{
  "name": "FireSting光学氧测量仪",
  "name_en": "FireSting optical oxygen meter",
  "manufacturer": "PyroScience",
  "description": "PyroScience FireSting 系列光学氧测量仪，用于连接光纤或探针式氧传感器，执行氧测量、零点/空气校准、背景校正，并读取温度、压力、湿度及测量结果寄存器，适用于溶解氧或气相氧实验监测。",
  "description_en": "A PyroScience FireSting series optical oxygen meter for fiber-optic or probe-based oxygen sensors. It performs oxygen measurements, zero/air calibration, background correction, and reads temperature, pressure, humidity, and result registers for dissolved-oxygen or gas-phase oxygen experiments.",
  "tag_hints": [
    "optical oxygen sensing",
    "fiber-optic oxygen meter",
    "oxygen calibration",
    "dissolved oxygen measurement",
    "phase-shift oxygen sensor",
    "temperature compensation",
    "multi-channel sensor"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 FireSting 设备，必要时自动尝试不同波特率。",
      "description_en": "Connect to the FireSting device, optionally trying different baud rates automatically."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与设备的连接。",
      "description_en": "Disconnect from the device."
    },
    {
      "action_name": "auto-send",
      "description": "向设备发送命令并校验回显与响应，失败时可重试。",
      "description_en": "Send a command to the device and validate the echo and response, with optional retry on failure."
    },
    {
      "action_name": "auto-write",
      "description": "向设备底层串口写入原始命令。",
      "description_en": "Write a raw command to the device serial interface."
    },
    {
      "action_name": "auto-read",
      "description": "从设备底层接口读取原始响应。",
      "description_en": "Read a raw response from the device interface."
    },
    {
      "action_name": "auto-read_unique_id",
      "description": "读取设备唯一标识号。",
      "description_en": "Read the device unique identifier."
    },
    {
      "action_name": "auto-blink",
      "description": "使设备标志灯闪烁，以便识别设备。",
      "description_en": "Blink the device logo or indicator for physical identification."
    },
    {
      "action_name": "auto-calibrate_zero",
      "description": "对指定通道执行零氧校准。",
      "description_en": "Perform zero-oxygen calibration on the specified channel."
    },
    {
      "action_name": "auto-calibrate_air",
      "description": "对指定通道执行空气点校准。",
      "description_en": "Perform air-point calibration on the specified channel."
    },
    {
      "action_name": "auto-trigger_oxygen_measurement",
      "description": "触发指定通道的氧测量。",
      "description_en": "Trigger an oxygen measurement on the specified channel."
    },
    {
      "action_name": "auto-trigger_temperature_measurement",
      "description": "触发指定通道的温度测量。",
      "description_en": "Trigger a temperature measurement on the specified channel."
    },
    {
      "action_name": "auto-trigger_pressure_measurement",
      "description": "触发指定通道的环境压力测量。",
      "description_en": "Trigger an ambient pressure measurement on the specified channel."
    },
    {
      "action_name": "auto-trigger_humidity_measurement",
      "description": "触发指定通道的湿度测量。",
      "description_en": "Trigger a humidity measurement on the specified channel."
    },
    {
      "action_name": "auto-clear_background",
      "description": "清除指定通道的背景校正寄存器。",
      "description_en": "Clear the background correction registers for the specified channel."
    },
    {
      "action_name": "auto-measure_background",
      "description": "测量并存储指定通道的背景相位与幅度。",
      "description_en": "Measure and store background phase and amplitude for the specified channel."
    },
    {
      "action_name": "auto-read_register",
      "description": "读取指定通道的单个寄存器。",
      "description_en": "Read a single register from the specified channel."
    },
    {
      "action_name": "auto-read_multiple_registers",
      "description": "读取指定通道的多个连续寄存器。",
      "description_en": "Read multiple consecutive registers from the specified channel."
    },
    {
      "action_name": "auto-write_register",
      "description": "向指定通道的单个寄存器写入值。",
      "description_en": "Write a value to a single register on the specified channel."
    },
    {
      "action_name": "auto-save_to_flash",
      "description": "将当前设置和校准数据保存到设备闪存。",
      "description_en": "Save current settings and calibration data to device flash memory."
    },
    {
      "action_name": "auto-load_from_flash",
      "description": "从设备闪存加载设置和校准数据。",
      "description_en": "Load settings and calibration data from device flash memory."
    },
    {
      "action_name": "auto-read_all_settings_registers",
      "description": "读取并解析指定通道的全部设置寄存器。",
      "description_en": "Read and parse all settings registers for the specified channel."
    },
    {
      "action_name": "auto-read_calibration_register",
      "description": "读取指定通道的单个校准寄存器。",
      "description_en": "Read a single calibration register from the specified channel."
    },
    {
      "action_name": "auto-read_cal_register_by_name",
      "description": "按名称读取指定通道的校准寄存器。",
      "description_en": "Read a calibration register by name from the specified channel."
    },
    {
      "action_name": "auto-read_bkgd_amp",
      "description": "读取指定通道的背景幅度值。",
      "description_en": "Read the background amplitude value for the specified channel."
    },
    {
      "action_name": "auto-read_bkgd_dphi",
      "description": "读取指定通道的背景相位角值。",
      "description_en": "Read the background phase-angle value for the specified channel."
    },
    {
      "action_name": "auto-read_all_cal_registers",
      "description": "读取并解析指定通道的全部校准寄存器。",
      "description_en": "Read and parse all calibration registers for the specified channel."
    },
    {
      "action_name": "auto-read_result_register",
      "description": "读取指定通道的单个结果寄存器。",
      "description_en": "Read a single result register from the specified channel."
    },
    {
      "action_name": "auto-read_result_register_by_name",
      "description": "按名称读取指定通道的结果寄存器。",
      "description_en": "Read a result register by name from the specified channel."
    },
    {
      "action_name": "auto-read_status",
      "description": "读取指定通道上一次测量的状态信息。",
      "description_en": "Read the status of the last measurement for the specified channel."
    },
    {
      "action_name": "auto-read_dphi",
      "description": "读取指定通道上一次测量的相位偏移 dphi。",
      "description_en": "Read the last measured phase shift dphi for the specified channel."
    },
    {
      "action_name": "auto-read_sample_temperature",
      "description": "读取指定通道上一次测量的样品温度。",
      "description_en": "Read the last measured sample temperature for the specified channel."
    },
    {
      "action_name": "auto-read_pressure",
      "description": "读取指定通道上一次测量时的环境压力。",
      "description_en": "Read the ambient pressure recorded during the last measurement for the specified channel."
    },
    {
      "action_name": "auto-read_signal_intensity",
      "description": "读取指定通道上一次测量的信号强度。",
      "description_en": "Read the signal intensity from the last measurement for the specified channel."
    },
    {
      "action_name": "auto-read_ambient_light",
      "description": "读取指定通道上一次测量的环境光强。",
      "description_en": "Read the ambient light level from the last measurement for the specified channel."
    },
    {
      "action_name": "auto-read_all_result_registers",
      "description": "读取并解析指定通道全部结果寄存器中的最近一次测量结果。",
      "description_en": "Read and parse all result registers containing the most recent measurement for the specified channel."
    },
    {
      "action_name": "auto-write_temperature_setting",
      "description": "设置指定通道的温度补偿值。",
      "description_en": "Set the temperature compensation value for the specified channel."
    },
    {
      "action_name": "auto-write_pressure_setting",
      "description": "设置指定通道的环境压力补偿值。",
      "description_en": "Set the ambient pressure compensation value for the specified channel."
    },
    {
      "action_name": "auto-write_salinity_setting",
      "description": "设置指定通道的盐度补偿值。",
      "description_en": "Set the salinity compensation value for the specified channel."
    },
    {
      "action_name": "auto-write_measure_time_setting",
      "description": "设置指定通道的测量时间。",
      "description_en": "Set the measurement time for the specified channel."
    },
    {
      "action_name": "auto-write_intensity_setting",
      "description": "设置指定通道的 LED 激发强度。",
      "description_en": "Set the LED excitation intensity for the specified channel."
    },
    {
      "action_name": "auto-write_amplification_setting",
      "description": "设置指定通道的信号放大倍数。",
      "description_en": "Set the signal amplification factor for the specified channel."
    },
    {
      "action_name": "auto-write_frequency_setting",
      "description": "设置指定通道的调制频率。",
      "description_en": "Set the modulation frequency for the specified channel."
    },
    {
      "action_name": "auto-write_fiber_type_setting",
      "description": "设置指定通道连接的传感器光纤类型。",
      "description_en": "Set the connected sensor fiber type for the specified channel."
    },
    {
      "action_name": "auto-write_calibration_register_by_name",
      "description": "按名称写入指定通道的校准寄存器。",
      "description_en": "Write a calibration register by name for the specified channel."
    },
    {
      "action_name": "auto-write_bkgd_amp",
      "description": "手动写入指定通道的背景幅度值。",
      "description_en": "Manually write the background amplitude value for the specified channel."
    },
    {
      "action_name": "auto-write_bkgd_dphi",
      "description": "手动写入指定通道的背景相位角值。",
      "description_en": "Manually write the background phase-angle value for the specified channel."
    }
  ]
}

